import { readdirSync } from 'node:fs';
import { expect, test } from 'vitest';
import { CHANGELOG } from '../src/lib/changelog';
import { changelogIndex, ENTRIES_DIR, ENTRY_FILE } from './changelog-index';

test('the index imports the entry files newest first and skips anything else in the folder', () => {
  expect(changelogIndex(['20261101-090000.ts', 'index.ts', '20261102-080000.ts', 'notes.md'])).toBe(
    [
      '// Generated by scripts/changelog-index.ts from the entry files in this folder. Do not edit or commit it.',
      "import e0 from './20261102-080000';",
      "import e1 from './20261101-090000';",
      '',
      'export const ENTRIES = [e0, e1];',
      '',
    ].join('\n'),
  );
});

test('every file in the entries folder is an entry named after its own moment, and the changelog holds them all', () => {
  const files = readdirSync(ENTRIES_DIR).filter((n) => n !== 'index.ts');
  expect(files.filter((n) => !ENTRY_FILE.test(n))).toEqual([]);
  const fileOf = (at: string) => `${at.slice(0, 10).replaceAll('-', '')}-${at.slice(11, 19).replaceAll(':', '')}.ts`;
  expect(CHANGELOG.map((x) => fileOf(x.at))).toEqual([...files].sort().reverse());
});
